/* ⛔ GENERATED by kit/build.mjs from i18n/id.json, the changelog and the kit. Do not edit. */
(window.FREALLY_I18N = window.FREALLY_I18N || {})["id"] = {"hero.headline":"<span class=\"hl-muted\">Chain vokal setiap era.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Satu plugin.</span>","hero.cycle":"Satu plugin.|Di vokalmu.|Di setiap DAW.","hero.sub":"Cari seorang artis, pilih sebuah era, tekan play. Takelight memuat seluruh chain vokal — tuning, EQ, kompresi, de-essing, delay, reverb, dan bus vokal — yang dibangun dari modulnya sendiri. Offline dan 100% tanpa AI.","price.note":"Belum ada yang dijual. Mulai versi 1.0, Freally Takelight akan dijual sebagai lisensi sekali bayar, didahului uji coba gratis seluruh plugin.","hero.chipStandalone":"Mandiri","what.title":"Apa ini","what.p1":"Vokal mentah tidak terdengar seperti rekaman, dan jaraknya adalah sebuah chain: tuning, EQ, kompresor, de-esser, delay dan reverb di send, serta bus vokal, dalam urutan yang tepat, dengan pengaturan yang tepat.","what.p2":"Takelight menyimpan satu chain utuh untuk setiap artis dan era di dalam satu plugin, dibangun dari modulnya sendiri, jadi kamu tidak pernah butuh plugin lain untuk mendengarnya.","what.p3":"Muat sebuah chain dan ia masuk dengan crossfade, tanpa bunyi klik. Bentuk dengan empat makro, atau buka rack dan putar kenop mana pun.","features.title":"Apa isinya","featuresPage.cards.chains.title":"Chain per artis dan era","featuresPage.cards.chains.body":"Ketik seorang artis, pilih era dan peran — lead atau ad-lib — dan seluruh chain dimuat berurutan: insert, return efek, dan bus vokal.","featuresPage.cards.swap.title":"Ganti tanpa bunyi klik","featuresPage.cards.swap.body":"Ganti chain saat trek diputar. Chain baru disiapkan terpisah dari audio dan masuk dengan crossfade 30 milidetik, jadi tidak ada yang berbunyi pop.","featuresPage.cards.joint.title":"Joint","featuresPage.cards.joint.body":"Satu rack memuat seluruh chain: koreksi nada, empat jenis EQ, enam jenis kompresor, de-esser, gate, saturasi, exciter, lo-fi, limiter, doubler, chorus, flanger, phaser, pan otomatis, delay, reverb, empat return, dan satu bus vokal.","featuresPage.cards.modes.title":"Sederhana dan Lanjutan","featuresPage.cards.modes.body":"Sederhana menampilkan empat makro — Penyetel Nada, Warna Suara, Ruang, dan Takaran. Lanjutan menampilkan setiap modul sebagai perangkat keras yang dirender, dengan setiap kartu menggambarkan apa yang dilakukan modulnya — kurva EQ di atas vokal Anda, kurva kompresor beserta seberapa banyak yang diredamnya — dan setiap kenop bisa diotomatisasi.","featuresPage.cards.daw.title":"Di setiap DAW","featuresPage.cards.daw.body":"CLAP dan VST3 di Windows, macOS, dan Linux, AU di macOS, serta sebuah aplikasi mandiri. Tersimpan bersama proyek Anda, melaporkan latensi agar DAW Anda menyelaraskan semuanya, dan aman dalam banyak instans sekaligus.","featuresPage.cards.offline.title":"Luring, privat, tanpa AI","featuresPage.cards.offline.body":"Tanpa akun, tanpa telemetri, dan tanpa model. Plugin dan aplikasi tidak pernah online; pemeriksaan pembaruan dan aktivasi lisensi berjalan di pembantu terpisah, hanya saat Anda memintanya.","ladder.title":"Jalan menuju 1.0","ladder.intro":"Satu baris per versi. Ini adalah tangga yang sama yang diikuti rencana pribadi — jika salah satu bergerak, keduanya bergerak, dan sebuah gerbang build membandingkan keduanya.","ladder.rung.v0.1.0":"Fondasi: plugin dimuat sebagai CLAP, VST3, dan AU serta sebagai aplikasi mandiri, meneruskan audio Anda tanpa diubah, meminta Anda menyetujui lisensinya, dan setiap gerbang kualitas berjalan.","ladder.rung.v0.2.0":"Joint: satu rack untuk seluruh chain vokal, modul EQ, dinamika, dan warna pertama di perangkat keras yang dirender, serta lampu rekam.","ladder.rung.v0.3.0":"Ruang: delay, reverb, doubling, lebar stereo, dan empat return efek, mengikuti tempo proyek Anda.","ladder.rung.v0.4.0":"Penyetel Nada: koreksi nada dari pemrosesan sinyal klasik, kunci nada ditemukan dari vokal Anda, dan mode latensi rendah untuk merekam.","ladder.rung.v0.5.0":"Cahaya pertama: cari seorang artis dan era, dan seluruh chain dimuat dengan satu klik. Versi lengkap pertama.","ladder.rung.v0.5.5":"Input Check, chain ad-lib, preset Anda sendiri, dan urungkan.","ladder.rung.v0.5.6":"Kartu visual: setiap modul menunjukkan apa yang dilakukannya — kurva EQ di atas spektrum langsung vokal Anda, kurva kompresor beserta seberapa banyak yang diredamnya — bukan sekadar kenop.","ladder.rung.v0.6.0":"Gelombang pertama chain artis, satu chain untuk setiap genre, dan halaman daftar artis.","ladder.rung.v0.6.1":"Gelombang pertama lengkap: sisa artisnya, dan prosesor yang dibutuhkan chain mereka — penekan resonansi, pembentuk transien, ducker yang memberi ruang bagi vokal, pompa yang mengikuti ketukan, reverb shimmer, dan kompresi ke atas.","ladder.rung.v0.7.0":"Di setiap DAW: tersimpan bersama proyek Anda, bisa diotomatisasi, latensinya dilaporkan, dan aman dalam banyak instans sekaligus.","ladder.rung.v0.8.0":"Aplikasi mandiri dengan kekuatan penuh, dan Takelight di macOS dan Linux.","ladder.rung.v0.9.0":"Gelombang kedua chain artis, serta putaran realisme dan performa.","ladder.rung.v0.9.5":"Reference Match: muat sebuah referensi, dan Takelight membaca penunda, gaung, warna suara, dan unsur lain dari vokalnya, lalu mengusulkannya pada modul-modulnya sendiri.","ladder.rung.v1.0.0-beta":"Diperkuat: pemasang untuk tiga sistem, pemeriksaan pembaruan, uji coba dan lisensi, serta manual lengkap. Masih tanpa unduhan di situs ini.","ladder.rung.v1.0.0-rc":"Kandidat rilis: setiap berkas ditinjau dan setiap host diuji secara manual.","ladder.rung.v1.0.0":"Rilis: uji coba gratis, lisensi sekali bayar, dan unduhan pertama yang pernah ditawarkan situs ini.","ladder.rung.v1.1.0":"Vocal Match: warna suara vokal Anda disetel terhadap referensi milik Anda sendiri.","ladder.rung.v1.2.0":"Double dan harmoni, ditumpuk untuk Anda.","ladder.rung.v1.3.0":"Gelombang ketiga chain artis, dan chain kiriman para produser.","ladder.rung.v1.4.0":"Jembatan ke Freally MIDI Master dan Freally Unloop.","ladder.rung.v1.5.0":"Pro Tools sebagai plugin (AAX), jika ketentuan Avid mengizinkan.","ladder.note":"Versi yang selesai sudah dibangun dan ditandai (tag). Itu bukan unduhan: tidak ada satu pun, dan tidak akan ada sampai 1.0.0.","honest.title":"Hal-hal yang oleh kebanyakan situs diletakkan di paling bawah","honest.voice.title":"Chain bukanlah suara","honest.voice.body":"Sebuah chain mereproduksi pemrosesan: tuning, EQ, kompresi, delay, dan reverb. Suara Anda, mikrofon Anda, ruangan Anda, dan cara Anda membawakan tetap milik Anda, dan tidak ada preset yang membuat seseorang terdengar seperti orang lain.","honest.start.title":"Chain adalah titik awal","honest.start.body":"Chain adalah tempat vokalmu bermula, bukan janji sebuah suara. Putar makronya, buka rack, dan jadikan milikmu; apa pun yang kamu ubah tidak pernah dikunci.","honest.downloads.title":"Tidak ada unduhan sebelum 1.0.0","honest.downloads.body":"Tanpa beta di halaman ini, tanpa build pratinjau, tanpa akses awal. Versi 1.0 datang dengan uji coba gratis seluruh plugin dan lisensi sekali bayar.","honest.network.title":"Ia tidak pernah daring","honest.network.body":"Plugin dan aplikasi mandiri sama sekali tidak berisi kode jaringan, dan gerbang build gagal jika ada yang ditambahkan. Pemeriksaan pembaruan dan aktivasi lisensi akan berada di pembantu terpisah yang hanya bertindak saat Anda memintanya.","site.tagline":"Chain vokal setiap era. Satu plugin.","footer.licence":"Perangkat lunak berpemilik — hak cipta dilindungi. © Mike Weaver. Bukan sumber terbuka. Kontak: freallyproducts@gmail.com.","footer.yours":"Audio, preset, dan proyek yang Anda buat dengan Freally Takelight milik Anda.","footer.disclaimer":"Nama artis hanya menunjukkan sebuah gaya. Freally Takelight tidak berafiliasi dengan, didukung, atau disetujui oleh artis, produser, engineer, label, publikasi, atau pembuat plugin mana pun. Sebuah chain menerapkan pemrosesan, bukan suara.","featuresPage.lead":"Satu plugin vokal dengan satu chain vokal utuh untuk setiap artis dan era — tuning, EQ, kompresi, de-essing, delay, reverb, dan bus vokal — yang dibangun dari modulnya sendiri.","featuresPage.version":"Halaman ini menggambarkan Freally Takelight versi 1.0: semua yang ada di sini ada di 1.0, dan tidak ada yang direncanakan setelah 1.0 yang tercantum.","featuresPage.numbers.plugin":"plugin untuk seluruh chain, tanpa plugin lain yang perlu dibeli","featuresPage.numbers.macros":"makro: Penyetel Nada, Warna Suara, Ruang, dan Takaran","featuresPage.numbers.returns":"return efek, ditambah satu bus vokal","featuresPage.numbers.plugins":"format plugin, ditambah aplikasi mandiri","featuresPage.numbers.systems":"sistem operasi: Windows, macOS, dan Linux","featuresPage.numbers.languages":"bahasa","featuresPage.numbers.ai":"model AI","featuresPage.numbers.borrowed":"impulse response, sampel, atau preset salinan","featuresPage.free.title":"Belum ada yang bisa dibeli","featuresPage.free.body":"Sebelum versi 1.0, tidak ada yang dijual dan tidak ada yang bisa diunduh. Setelah itu ada uji coba gratis seluruh plugin dan satu harga, dibayar sekali: tanpa langganan dan tanpa akun. Audio yang Anda buat dengannya milik Anda.","featuresPage.cards.title":"Apa yang dilakukan versi 1.0","featuresPage.cards.tune.title":"Penyetel Nada dan Auto Key","featuresPage.cards.tune.body":"Koreksi nada dari pemrosesan sinyal klasik, dengan kunci nada ditemukan dari vokal Anda atau sidechain, dan mode latensi rendah untuk merekam melaluinya.","featuresPage.cards.inputCheck.title":"Input Check dan A/B","featuresPage.cards.inputCheck.body":"Input Check mendengarkan sepuluh detik take Anda dan mengatur Kenop Input, serta gate, filter high-pass, dan de-esser yang ada di chain Anda. A/B membandingkan chain dengan file referensi yang Anda muat, dengan kenyaringan disamakan, atau dengan versi kedua dari chain itu sendiri; referensi tidak pernah disimpan.","featuresPage.cards.lightDark.title":"Terang dan gelap","featuresPage.cards.lightDark.body":"Mode gelap dan mode terang, keduanya dalam hijau Freally, dengan setiap kenop, fader, dan sakelar dirender di Blender untuk masing-masing mode, serta lampu rekam yang menyala saat chain aktif.","featuresPage.compare.title":"Berdampingan dengan alat komersial","featuresPage.compare.intro":"Freally Takelight 1.0 di samping plugin vokal yang dipakai produser saat menginginkan suara yang punya nama. Setiap sel produk lain berasal dari halaman pembuatnya atau liputan yang diterbitkan, diperiksa pada Oktober 2026; sel yang tidak bisa dipastikan dari halaman atau liputan itu bertuliskan belum diverifikasi.","featuresPage.compare.feature":"Fitur","featuresPage.compare.row.price":"Harga (USD, Oktober 2026)","featuresPage.compare.ourPrice":"Satu harga, sekali bayar, setelah uji coba gratis","featuresPage.compare.note.muzePrice":"seumur hidup, atau $24 setiap 4 minggu","featuresPage.compare.legend.unknown":"belum diverifikasi","featuresPage.compare.row.artists":"Chain yang dinamai sesuai artis","featuresPage.compare.legend.yes":"ada","featuresPage.compare.note.artistEra":"per artis, era, dan peran","featuresPage.compare.note.muzePresets":"52 preset artis","featuresPage.compare.legend.no":"tidak ada","featuresPage.compare.note.engineerChain":"chain satu engineer","featuresPage.compare.note.producerChain":"chain satu produser","featuresPage.compare.row.modes":"Mode Sederhana dan Lanjutan","featuresPage.compare.row.key":"Menemukan kunci nada dari vokal Anda","featuresPage.compare.row.formats":"CLAP, VST3, dan AU","featuresPage.compare.legend.partly":"sebagian","featuresPage.compare.row.systems":"Windows, macOS, dan Linux","featuresPage.compare.row.noAi":"Tanpa AI atau pembelajaran mesin","featuresPage.compare.summaryTitle":"Singkatnya","featuresPage.compare.summary":"Hanya Takelight yang punya chain menurut artis, era, dan peran, ketiga format plugin, Linux di samping Windows dan macOS, dan sama sekali tanpa AI.","featuresPage.compare.theyWinTitle":"Di mana mereka unggul","featuresPage.compare.theyWin":"Muze saat ini punya 52 preset artis dan berjalan di Pro Tools; chain artis pertama Takelight telah tiba di versi 0.5.0, dan di versi 1.0 ia bukan plugin Pro Tools. CLA Vocals dan The Spirit dibuat bersama engineer dan produser yang namanya mereka pakai.","featuresPage.compare.asOf":"Kolom Takelight adalah versi 1.0, yang belum dirilis. Produk lain juga berubah; tabel ini per Oktober 2026. Nama produk milik pemiliknya masing-masing dan di sini hanya dipakai untuk membandingkan.","featuresPage.why.title":"Mengapa ia dibuat seperti ini","featuresPage.why.built.title":"Dibangun, bukan dipinjam","featuresPage.why.built.body":"Setiap modul adalah pemrosesan sinyal klasik milik Takelight sendiri. Tanpa impulse response, tanpa sampel, tanpa kode pinjaman, dan tanpa pengaturan yang disalin dari preset produk lain.","featuresPage.why.names.title":"Nama yang jujur","featuresPage.why.names.body":"Sebuah chain dinamai menurut artis dan eranya, tidak lebih. Tanpa rupa, tanpa sampul, dan tanpa janji membuat siapa pun terdengar seperti orang lain.","featuresPage.why.reference.title":"Referensimu, setara levelnya","featuresPage.why.reference.body":"A/B menaruh file referensi yang kamu muat di samping vokalmu dengan kenyaringan yang sama, agar versi yang lebih keras tidak pernah menipu telingamu. Referensi tetap di memori dan tidak pernah disimpan.","featuresPage.why.local.title":"Ia tetap di komputer Anda","featuresPage.why.local.body":"Tanpa telemetri dan tanpa cloud. Vokal Anda tidak pernah meninggalkan komputer, dan gerbang build gagal jika kode jaringan pernah ditambahkan ke plugin atau aplikasi.","featuresPage.why.roster.title":"Satu daftar untuk keluarga","featuresPage.why.roster.body":"Artis dan genre berbagi nama dengan Freally MIDI Master dan Freally Unloop, jadi satu daftar berjalan di seluruh lini Freally.","featuresPage.coming.title":"Apa yang masih akan datang","featuresPage.coming.intro":"Dikatakan terus terang, karena daftar fitur yang menyembunyikan celahnya tidak layak dibaca. Halaman ini menggambarkan versi 1.0, dan Takelight dibangun satu anak tangga demi satu: belum semuanya selesai dibangun. Setiap anak tangga di jalan menuju 1.0 ditandai dengan statusnya.","featuresPage.limits.title":"Apa yang tidak dilakukan 1.0","featuresPage.limits.voice":"Ia tidak mengubah siapa yang bernyanyi, dan tidak pernah meniru suara.","featuresPage.limits.roster":"Belum semua artis ada. Daftarnya bertambah di setiap versi.","featuresPage.limits.match":"Ia tidak mencocokkan vokal Anda dengan referensi secara otomatis; Vocal Match direncanakan setelah 1.0.","featuresPage.limits.aax":"Di versi 1.0 ia bukan plugin Pro Tools (AAX).","featuresPage.coming.downloads":"Tidak ada unduhan sebelum versi 1.0, dan tidak ada di halaman ini.","docs.intro":"Manual ini bertambah di setiap versi. Saat ini manual ini membahas cara menemukan chain, preset Anda, mode Sederhana dan empat kenopnya, A/B, rack dan apa yang ditampilkan setiap kartu, urungkan, empat kanal return efeknya, Penyetel Nada, Input Check, dan tiga puluh modulnya.","docs.start.title":"Memulai","docs.browser.title":"Menemukan chain","docs.presets.title":"Preset Anda","docs.simple.title":"Mode Sederhana dan empat kenop","docs.ab.title":"A/B","docs.rack.title":"Rack","docs.cards.title":"Apa yang ditampilkan setiap kartu","docs.undo.title":"Urungkan dan ulangi","docs.returns.title":"Kanal return dan lemparan","docs.tune.title":"Penyetel Nada dan Auto Key","docs.inputCheck.title":"Input Check","docs.automation.title":"Otomatisasi","docs.lamp.title":"Lampu rekam dan meter","docs.modules.title":"Modul","docs.project.title":"Tersimpan bersama proyek Anda","docs.agreement.title":"Perjanjian lisensi","docs.settings.title":"Pengaturan","docs.language.title":"Bahasa","docs.disclaimer.title":"Penafian","docs.privacy.title":"Privasi dan jaringan","docs.report.title":"Saat terjadi masalah","docs.start.p1":"Takelight berjalan di dalam DAW Anda sebagai plugin CLAP, VST3, atau AU, atau sendiri sebagai aplikasi mandiri. Pasang di trek vokal. Takelight terbuka dalam mode Sederhana: cari artis atau genre, pilih era dan peran, dan seluruh chain dimuat. Sampai Anda memuat chain atau menambahkan modul, audio Anda lewat tanpa perubahan.","docs.start.p2":"Tidak ada unduhan sebelum versi 1.0.0, dan kodenya privat.","docs.browser.p1":"Ketik di kolom pencarian di bagian atas — artis, nama julukan, atau genre — atau tekan Ctrl+K (Cmd+K di Mac) dari mana saja. Chain muncul saat Anda mengetik: setiap artis dengan era-eranya, setiap era dengan tahun dan perannya, seperti lead, ad-lib, atau FX. Pilih satu dan seluruh chain dimuat berurutan, tanpa bunyi klik, sambil trek diputar. Tombol panah bergerak di dalam daftar, Enter memuat, dan Escape menutupnya.","docs.browser.p2":"Saat pencarian kosong, ia menawarkan chain yang terakhir Anda muat. Untuk artis yang belum punya chain, ia menawarkan chain dari genrenya, dan untuk nama yang tidak dikenalnya, ia mengatakannya dan menyarankan sebuah genre.","docs.browser.p3":"Versi 0.6.1 memiliki Drake dalam tiga era — So Far Gone (2009), Take Care (2011), dan era modern (2016–2026) — dengan chain FX dari era Take Care; empat puluh artis lain, era demi era; serta lead dan ad-lib untuk setiap genre dari 73 genre, dengan trap dalam dua dekade. Halaman Daftar gaya memuat semuanya. Setiap chain dinamai menurut artis atau genrenya dan eranya, tidak lebih.","docs.presets.p1":"Simpan preset… di bagian atas menyimpan chain seperti yang telah Anda bentuk — setiap modul, kenop, kirim, dan fader, serta empat kenop Sederhana — dengan nama pilihan Anda. Setiap preset adalah file di Dokumen › Freally Takelight › Presets, jadi Anda bisa mencadangkannya atau mengirimkannya ke seseorang.","docs.presets.p2":"Preset saya… menampilkan daftarnya, masing-masing dengan chain asalnya, untuk dimuat, diganti nama, diekspor, atau dihapus. Impor… memasukkan preset yang dikirim seseorang kepada Anda, dan memberi nomor pada namanya jika Anda sudah punya preset dengan nama itu. File yang bukan preset Takelight, lebih besar dari 256 KB, atau disimpan oleh versi yang lebih baru akan ditolak, dan daftarnya menyebutkan alasannya.","docs.presets.p3":"Preset Anda juga ada di pencarian, di bawah Preset saya. Saat chain asal sebuah preset diperbarui di versi berikutnya, preset dimuat ke chain yang diperbarui, mempertahankan setiap perubahan yang Anda buat, dan memberitahukannya.","docs.simple.p1":"Sederhana menampilkan lampu rekam, nama chain, empat kenop besar, serta meter Input dan Output; Lanjutan, dari sakelar di bagian atas, menampilkan seluruh rack. Proyek Anda mengingat tampilan yang terakhir Anda pakai, dan di Pengaturan Anda memilih tampilan untuk instans baru.","docs.simple.p2":"Penyetel Nada mengatur seberapa cepat dan seberapa alami vokal disetel. Warna Suara membuat chain lebih gelap atau lebih terang, di sekitar 1 kHz, dan de-esser mengikutinya. Ruang menaikkan atau menurunkan semua level kirim efek bersama-sama, hingga 12 dB. Takaran mengatur seluruh chain terhadap vokal kering Anda, dari kering pada 0 % hingga chain penuh pada 100 %.","docs.simple.p3":"Dengan Penyetel Nada, Warna Suara, dan Ruang di tengah serta Takaran pada 100 %, chain berbunyi seperti saat dibuat, dan setiap chain dimuat dengan cara itu. Setiap kenop adalah parameter host, jadi DAW Anda dapat mengotomatisasinya, dan klik ganda mengembalikannya ke nilai bawaan.","docs.ab.p1":"Muat referensi… membuka dialog file sistem Anda, atau letakkan file di jendela. Ia membaca WAV, AIFF, FLAC, dan MP3, hingga 20 menit, dan bilahnya menampilkan nama file, durasi, dan kenyaringannya. B memutar referensi dari posisi DAW Anda (dari awal di aplikasi mandiri), A adalah chain Anda, dan setiap peralihan berupa crossfade 20 milidetik.","docs.ab.p2":"Samakan kenyaringan memutar referensi pada kenyaringan vokal Anda, jadi Anda menilai warna suaranya, bukan levelnya. Referensi hanya disimpan di memori: tidak pernah disimpan bersama proyek Anda, preset, atau di tempat lain mana pun, dan file di drive jaringan ditolak.","docs.ab.p3":"Bandingkan chain menyimpan dua versi chain Anda. A adalah yang sedang Anda ubah; tekan B dan ia dimulai sebagai salinan, jadi tidak ada yang berubah; ubahlah, dan A serta B masing-masing menyimpan versinya sendiri. Keduanya disimpan bersama proyek Anda.","docs.rack.p1":"Rack memuat seluruh chain sesuai urutan sinyal, dalam empat baris: Tahap awal (slot F1 dan F2), Insert (I1 hingga I12), empat Kanal return efek (A hingga D, slot R1 hingga R12), dan Bus (B1 hingga B4).","docs.rack.p2":"Pilih modul dari menu slot kosong untuk menambahkannya. Kartunya menampilkan setiap kontrol yang dimilikinya: kenop untuk nilai, sakelar, dan menu untuk pilihan. Kepalanya memuat karakternya (bila ada lebih dari satu), Bypass (B), Solo (S), dan × untuk mengeluarkannya.","docs.rack.p3":"Setiap perubahan bebas klik. Modul yang Anda tambahkan atau keluarkan memudar masuk atau keluar, karakter baru masuk dengan crossfade, dan setiap kenop bergerak halus, jadi Anda bisa bekerja sambil trek diputar. Modul yang di-bypass tetap mempertahankan latensinya, jadi DAW Anda tetap selaras waktunya.","docs.rack.p4":"Setiap kontrol bisa dioperasikan dari papan ketik. Tab berpindah di antara kontrol; tombol panah memutar kenop, dan Shift memutarnya dengan langkah lebih besar; Home dan End membawanya ke salah satu ujung; klik ganda mengembalikannya ke nilai bawaan.","docs.rack.p5":"Sebuah rack memuat kenop sebanyak yang dapat digerakkan Takelight sekaligus — setiap slot yang terisi modul terbesar akan melebihinya — jadi setelah batas itu, modul ditolak dan rack memberi tahu bahwa ia penuh.","docs.cards.p1":"Di samping kenopnya, kartu setiap modul menggambarkan apa yang dilakukan modul itu, dihitung dari matematika yang sama yang menghasilkan suaranya. EQ — EQ Parametrik, EQ Konsol, dan EQ Program — menggambar kurvanya di atas vokal Anda saat diputar: spektrumnya sebelum EQ, redup, dan sesudahnya, terang, dengan puncak-puncaknya ditahan sejenak. Setiap band memiliki titik di kurva: seret titik itu untuk menggeser frekuensi dan gain band sekaligus, putar roda mouse di atasnya untuk mengatur lebarnya, klik ganda untuk mengembalikan band, atau gunakan tombol panah. Satu seretan utuh adalah satu langkah urungkan. De-esser menggambar band yang didengarkannya dan potongan yang dibuatnya, dan Trim menggambar high-pass-nya.","docs.cards.p2":"Kompresor, Penyetara level otomatis, dan Limiter menggambar kurvanya — level input terhadap level output — dengan titik di tempat vokal Anda berada pada kurva saat ini, dan di bawahnya reduksi gain empat detik terakhir. Nada yang stabil menempatkan titik di kurva; serangan yang tajam bisa mengangkatnya ke atas kurva sejenak, sebelum kompresor menangkapnya. Seret ambang batas di sepanjang kurva, atau gunakan tombol panah: itu memutar kenop yang mengaturnya. Kartu Gate menunjukkan level yang didengarnya terhadap ambang batasnya, diarsir di bagian saat ia tertutup.","docs.cards.p3":"Penunda menggambar pengulangannya pada garis waktu terhadap ketukan dan birama proyek Anda, masing-masing sekeras yang disisakan oleh umpan balik dan filter; pada Ping-pong, pengulangan kiri berada di atas garis dan yang kanan di bawahnya. Gaung menggambar peluruhannya — pra-tunda, pantulan awal, dan ekornya — dan Gate terbalik menggambar kresendonya. Pengganda, Efek chorus, dan Lebar menampilkan citra stereo dari atas, dan Saturasi, Eksiter, dan Efek lo-fi menampilkan kurvanya serta harmonik yang ditambahkan kurva itu pada vokal Anda saat ini.","docs.cards.p4":"Hanya kartu yang tampak di layar yang menggambar, dan hingga delapan kartu EQ menampilkan spektrum vokal Anda sekaligus. Penyetel Nada memiliki grafik nadanya sebagai gantinya, dan Penggeser Nada hanya kenopnya.","docs.undo.p1":"Panah di bagian atas mengurungkan dan mengulangi setiap perubahan pada suara, hingga 100 langkah: sebuah kenop (satu seretan utuh adalah satu langkah), modul yang ditambahkan atau dikeluarkan, karakternya, Bypass dan Solo, kirim dan fader, empat kenop Sederhana, Kenop Input, chain atau preset yang dimuat, dan Terapkan dari Input Check. Ctrl+Z mengurungkan, dan Ctrl+Shift+Z atau Ctrl+Y mengulangi (⌘Z dan ⌘⇧Z di Mac), selama jendela Takelight sedang fokus, sehingga DAW Anda tetap memakai pintasannya sendiri.","docs.undo.p2":"Tampilan, tema, bahasa, dan referensi A/B tidak pernah diurungkan, begitu pula otomatisasi DAW Anda. Setiap proyek dimulai dengan riwayat baru saat dibuka, begitu juga setiap sisi perbandingan saat Anda beralih ke sana.","docs.returns.p1":"Masing-masing dari empat kanal return, A hingga D, diumpankan dari ujung baris Insert lewat kenop Kirim-nya, dari mati hingga +6 dB. Vokal melewati tiga slot kanal return itu — misalnya penunda dan gaung — dan fader kanal return menentukan seberapa banyak yang bergabung dengan vokal kering dalam perjalanannya ke Bus.","docs.returns.p2":"Tahan tombol Lempar sebuah kanal return dan vokal dilempar ke dalamnya: level kirimnya naik ke 0 dB, lalu turun kembali saat Anda melepasnya, masing-masing dalam 5 milidetik. Lempar A hingga D juga merupakan parameter host, jadi DAW Anda bisa merekam lemparan dan memutarnya kembali — ekor penunda pada satu kata.","docs.returns.p3":"Penunda yang diatur ke nilai not tetap seirama dengan tempo proyek Anda, dan mengikutinya saat tempo berubah di tengah lagu.","docs.tune.p1":"Penyetel Nada menarik setiap nada yang dinyanyikan ke nada terdekat dalam tangga nadanya. Kecepatan koreksi menentukan seberapa cepat: pada 0 ms suara melompat dari nada ke nada, suara yang keras dan berundak; lebih lambat, suara meluncur ke sana, dan pada beberapa ratus milidetik penyetelannya hampir tak terdengar. Humanisasi membiarkan nada panjang mengendap lebih lambat, dan Kelenturan menjaga luncuran dan vibrato yang paling jauh menyimpang dari nada. Forman suara tetap di tempatnya, jadi karakternya terjaga, dan napas serta konsonan lewat tanpa tersentuh.","docs.tune.p2":"Menu Tangga nada dimulai pada Auto Key: Penyetel Nada mendengarkan vokal Anda dan menetapkan tangga nadanya dalam sekitar empat detik nyanyian; sampai saat itu ia menyetel ke semitone terdekat, sementara lampu rekam menyala amber. Kartu menunjukkan tangga nada yang didengarnya, dan Kunci menahannya. Atau pilih sendiri Kromatik atau salah satu dari 24 tangga nada. Jika belum ada tangga nada yang terdengar setelah 20 detik bernyanyi, kartu meminta Anda memilih satu.","docs.tune.p3":"Grafik nada menampilkan empat detik terakhir: nada yang Anda nyanyikan sebagai garis tipis dan nada yang diteruskan Penyetel Nada sebagai garis hijau, di atas garis untuk nada yang ditujunya.","docs.tune.p4":"Untuk mendengar sebuah nada sebelum menyetelnya, Penyetel Nada menunggu 21 milidetik, dan Takelight melaporkannya ke DAW Anda, sehingga vokal tetap seirama dengan beat. Saat merekam, jeda itu akan terdengar di headphone Anda, jadi parameter host Tracking, pada Auto, menurunkan Penyetel Nada ke 4 milidetik setiap kali DAW Anda merekam, dan kartu memberitahukannya. Setel Tracking ke On atau Off untuk memilih sendiri.","docs.tune.p5":"Sebuah rack memuat satu Penyetel Nada, karena satu Penyetel Nada menyetel seluruh vokal.","docs.tune.p6":"Auto Key juga bisa menemukan tangga nada dari beat. Kirim beat ke input sidechain Takelight di DAW Anda dan setel Mendengarkan, di kartu Penyetel Nada, ke Sidechain: Penyetel Nada mengikuti akor beat. Proyek Anda mengingat pilihan itu, dan Pengaturan menetapkannya untuk proyek baru. Selama tidak ada yang diputar di sidechain, Penyetel Nada mendengarkan vokal Anda, dan kartu memberitahukannya.","docs.inputCheck.p1":"Input Check, di bagian atas rack, menyiapkan Anda sebelum merekam. Tekan tombolnya lalu nyanyikan atau mainkan take Anda selama sepuluh detik; lampu rekam menyala amber selama ia mendengarkan. Ia butuh setidaknya dua detik suara, dan meminta lagi bila yang terdengar terlalu sedikit.","docs.inputCheck.p2":"Lalu ia menunjukkan yang terdengar — puncak, level, kenyaringan, derau dasar, gemuruh di bawah 80 Hz, sibilansi, dan plosif — dan yang disarankan: Kenop Input, untuk membawa suara Anda ke level yang sehat, serta ambang batas gate, filter high-pass, dan ambang batas de-esser. Ia hanya mengatur modul yang sudah ada di chain Anda; modul yang tidak ada bertuliskan Tidak ada di chain ini, dan tidak ada yang ditambahkan untuk Anda.","docs.inputCheck.p3":"Tidak ada yang berubah sampai Anda menekan Terapkan, dan Urungkan membatalkan seluruh Terapkan dalam satu langkah. Buang membiarkan semuanya seperti semula. Jika take mengalami clipping, ia meminta Anda menurunkan gain interface Anda, karena clipping tidak bisa diurungkan setelah direkam.","docs.automation.p1":"Setiap slot memiliki 24 parameter host, dinamai menurut slotnya (F1 hingga B4), dan kenop serta sakelar sebuah modul memakainya secara berurutan, sehingga DAW Anda dapat mengotomatisasinya. Daftar parameter tidak pernah berubah saat Anda menambah, menukar, atau menghapus modul.","docs.automation.p2":"Beberapa pengaturan tidak diotomatisasi, karena mengubahnya di tengah nada akan menimbulkan bunyi klik: tipe dan kemiringan band EQ, kemiringan filter, dan mode seperti deteksi de-esser. Semuanya tetap tersimpan bersama proyek Anda.","docs.lamp.p1":"Lampu rekam di bagian atas rack menyala hijau saat ada modul di rack dan suara Anda masuk, berkedip merah saat input mengalami clipping, dan padam di luar itu. Lampu ini berubah menjadi kuning amber saat Auto Key pada Penyetel Nada mendengarkan untuk mencari tangga nada, dan saat Input Check mendengarkan.","docs.lamp.p2":"Meter Input dan Output di kedua sisi menampilkan kanal kiri dan kanan, dan di samping meter Input, Kenop Input mengatur level yang masuk, dari −24 hingga +24 dB; DAW Anda dapat mengotomatiskannya. Masing-masing meter punya lampu clip yang tetap menyala sampai Anda mengkliknya. Kartu kompresor menunjukkan seberapa banyak ia menurunkan vokal, selama ia melakukannya.","docs.modules.p1":"Versi 0.6.1 memiliki tiga puluh empat modul. Masing-masing adalah rancangan Takelight sendiri, dan tidak ada yang mengaku sebagai produk lain.","docs.modules.tune.title":"Penyetel Nada","docs.modules.tune.p1":"Koreksi nada ke sebuah tangga nada — Auto Key, Kromatik, atau salah satu dari 24 — dengan kecepatan koreksi 0 hingga 400 ms, Humanisasi dan Kelenturan, serta grafik nada yang dinyanyikan dan disetel. Satu per rack; lihat Penyetel Nada dan Auto Key di atas.","docs.modules.trim.title":"Trim","docs.modules.trim.p1":"Gain, polaritas, dan filter high-pass dengan pilihan kemiringan: hal pertama di sebagian besar chain.","docs.modules.parametric.title":"EQ Parametrik","docs.modules.parametric.p1":"Delapan band, masing-masing bell, shelf, potong, atau notch, dengan potongan dari 6 hingga 96 dB per oktaf. Kenopnya menampilkan satu band sekaligus — pilih band menurut nomornya — dan setiap band memiliki titiknya di kurva.","docs.modules.console.title":"EQ Konsol","docs.modules.console.p1":"EQ kanal sebuah konsol mixing: filter high-pass dan low-pass serta empat band, dalam empat karakter — Inggris E, Inggris G, Kelas A, dan Q Proporsional.","docs.modules.program.title":"EQ Program","docs.modules.program.p1":"Boost dan cut yang lebar dan lembut di ujung rendah dan tinggi, serta tahap tabung untuk kehangatan.","docs.modules.dynamiceq.title":"EQ Dinamis","docs.modules.dynamiceq.p1":"Dua band, masing-masing bell atau shelf, yang gain-nya bergerak mengikuti level di bagian vokalnya sendiri: rentang negatif memotong area yang kasar atau menggema hanya saat keras, rentang positif mengangkatnya saat suara naik. Setiap band punya frekuensi, Q, ambang, rasio, dan rentang, dengan satu attack, release, dan output.","docs.modules.resonance.title":"Penekan Resonansi","docs.modules.resonance.p1":"Menemukan bagian tempat suara berdengung di atas frekuensi di sekitarnya dan hanya menurunkan bagian itu, hanya selama berdengung: 24 band sempit di rentang yang Anda tentukan, dengan kedalaman, selektivitas, ketajaman, attack, dan release. Ia tidak pernah melihat ke depan, jadi tidak menambah latensi dan bekerja saat Anda merekam.","docs.modules.opto.title":"Kompresor Optik","docs.modules.opto.p1":"Perataan level yang halus dan mengikuti performa, dari satu kenop Reduksi puncak, dalam karakter Optik dan Optik tabung, dengan kompresi atau pembatasan.","docs.modules.fet.title":"Kompresor FET","docs.modules.fet.p1":"Cepat dan maju ke depan, dengan rasio tetap dan pengaturan Semua untuk kompresi agresif, serta kontrol Mix untuk kompresi paralel.","docs.modules.vca.title":"Kompresor VCA","docs.modules.vca.p1":"Bersih dan presisi, dalam karakter Bus dan Kanal, dengan deteksi RMS atau puncak, high-pass sidechain, dan kontrol Mix.","docs.modules.multiband.title":"Kompresor multiband","docs.modules.multiband.p1":"Membagi vokal menjadi band rendah, tengah, dan tinggi di dua titik crossover dan mengompresi masing-masing sendiri, dengan ambang, rasio, dan gain per band serta satu attack, release, knee, output, dan mix. Saat tidak ada yang dikurangi, band-band itu menyatu kembali menjadi vokal seperti semula. Separuh naiknya mengangkat apa yang jatuh di bawah ambang naik setiap band, hingga batas yang Anda tentukan; pada 1:1 tidak ada yang diangkat.","docs.modules.varimu.title":"Kompresor vari-mu","docs.modules.varimu.p1":"Kompresor tabung yang rasionya naik makin keras ia bekerja, jadi ia mulai dengan lembut dan menahan dengan mantap, dengan enam konstanta waktu; 5 dan 6 melepas makin lambat makin lama ia sudah mengompresi.","docs.modules.punch.title":"Kompresor Punch","docs.modules.punch.p1":"Kompresor berkarakter dengan lima karakter, dari Normal hingga Distorsi 3, dengan Nuke untuk kompresi ekstrem dan kontrol Mix.","docs.modules.transient.title":"Pembentuk Transien","docs.modules.transient.p1":"Mengangkat atau melunakkan awal setiap suara dengan Attack, dan dengungnya dengan Tahan, apa pun levelnya, dengan Kecepatan dan Output. Nada yang ditahan lewat tanpa diubah, dan tidak menambah latensi.","docs.modules.vox.title":"Leveler Vokal","docs.modules.vox.p1":"Meratakan level vokal hanya dengan ambang batas dan output.","docs.modules.rider.title":"Penyetara level otomatis","docs.modules.rider.p1":"Menggiring level vokal ke arah kenyaringan sasaran — naik untuk kata-kata yang pelan, turun untuk yang keras — dalam rentang dan kecepatan yang Anda atur, dan membiarkan napas di antara frasa. Antisipasi 10 ms opsional membuatnya bergerak tepat sebelum sebuah kata; fitur ini menambah latensi 10 ms, yang diberitahukan Takelight ke DAW Anda.","docs.modules.deesser.title":"De-esser","docs.modules.deesser.p1":"Menjinakkan bunyi \"s\" yang tajam, pita terpisah atau pita lebar, dengan bell atau shelf, dan deteksi relatif atau absolut.","docs.modules.ducker.title":"Ducker Spektral","docs.modules.ducker.p1":"Menyingkirkan apa yang lewat dari jalan vokal, hanya di frekuensi yang diisi vokal, dan membiarkannya kembali di antara frasa, dengan jumlah, ambang, attack, release, dan rentang. Di kanal return ia mendengarkan vokal yang dikirim ke sana, jadi delay atau reverb memberi ruang bagi kata-kata.","docs.modules.gate.title":"Gate","docs.modules.gate.p1":"Gate atau ekspander di antara frasa, dengan tahan, histeresis, dan filter sidechain agar napas dan bocoran suara tidak membukanya.","docs.modules.pump.title":"Pompa","docs.modules.pump.p1":"Menurunkan vokal di setiap ketukan — atau setiap bar, setengah, seperdelapan, atau seperenam belas not — dan mengembalikannya mengikuti kurva, selaras dengan proyek Anda, sehingga vokal bergerak bersama kick. Kedalaman, laju, kurva, turun, dan geser.","docs.modules.saturation.title":"Saturasi","docs.modules.saturation.p1":"Pita magnetik, Tabung, Trafo, Mengembang, dan Klip, dengan oversampling agar harmonik yang ditambahkannya tetap bersih; Klip menahan puncak di skala penuh lewat knee yang pendek dan halus.","docs.modules.exciter.title":"Eksiter","docs.modules.exciter.p1":"Menambahkan harmonik di atas frekuensi yang Anda pilih — ganjil, genap, atau campuran keduanya — untuk kejernihan dan kesan lapang. Hanya harmoniknya yang ditambahkan; vokalnya sendiri lewat tanpa tersentuh.","docs.modules.lofi.title":"Efek lo-fi","docs.modules.lofi.p1":"Lebih sedikit bit dan laju sampel lebih rendah, dari 24 bit turun ke 4 dan dari 48 kHz turun ke 1 kHz, dengan dithering, filter anti-aliasing, drive, dan kontrol Mix.","docs.modules.limiter.title":"Limiter","docs.modules.limiter.p1":"Limiter true-peak: output tidak pernah melampaui batas atasnya, bahkan di antara sampel.","docs.modules.delay.title":"Penunda","docs.modules.delay.p1":"Lima karakter — Digital, Pita magnetik, Analog, Ping-pong, dan Gema pendek. Waktunya diatur dalam milidetik atau sebagai nilai not dari 1/64 hingga dua birama, termasuk triplet dan not bertitik, seirama dengan proyek Anda. Filter di umpan balik, peredaman di bawah vokal, dan lebar; di atas 100 % umpan balik, pengulangannya mengembang dan bertahan alih-alih lepas kendali.","docs.modules.reverb.title":"Gaung","docs.modules.reverb.p1":"Enam karakter — Pelat, Ruangan, Aula, Ruang gema, Suasana, dan Kilau — dengan pra-tunda, peluruhan dari 0.1 hingga 20 detik, ukuran, redaman, difusi, modulasi, dan filter di kanal return. Peluruhan adalah waktu yang dibutuhkan ekor gaung untuk turun 60 dB. Kilau memutar ekor gaung aula sekali lagi satu oktaf lebih tinggi, sebanyak yang diizinkan kenopnya.","docs.modules.reversegate.title":"Gate terbalik","docs.modules.reversegate.p1":"Gaung terbalik: setelah setiap bunyi, gelombang gaung yang membesar sepanjang durasi gate, dari 50 ms hingga satu detik, lalu berhenti mendadak. Ia tidak pernah melihat ke depan, jadi tidak menambah latensi dan bisa dipakai saat Anda merekam.","docs.modules.doubler.title":"Pengganda","docs.modules.doubler.p1":"Mengubah satu rekaman menjadi dua, tiga, atau empat suara, masing-masing sedikit terlambat, sedikit bergeser dalam waktu dan nada, dan tersebar di bidang stereo, dalam karakter Rapat dan Lebar. Saat dijumlahkan ke mono, levelnya tetap dekat dengan level vokal itu sendiri.","docs.modules.chorus.title":"Efek chorus","docs.modules.chorus.p1":"Efek chorus dua suara, satu suara naik nadanya sementara yang lain turun, dengan laju, kedalaman, mix, dan drive; pada mix 50 % levelnya tetap terjaga dan menyatu ke mono dengan bersih.","docs.modules.flanger.title":"Efek flanger","docs.modules.flanger.p1":"Delay pendek yang disapu naik turun perlahan dan diumpankan kembali ke dirinya sendiri, dengan rate, depth, delay, feedback, dan mix; sisi kanan menyapu seperempat siklus lebih dulu daripada sisi kiri, sehingga vokal mono ter-flange di seluruh bidang stereo.","docs.modules.phaser.title":"Efek phaser","docs.modules.phaser.p1":"Rangkaian 4, 8, atau 12 tahap all-pass yang disapu gelombang lambat, diumpankan kembali dan dicampur dengan vokal, dengan rate, depth, frekuensi, feedback, tahap, dan mix; sisi kanan menyapu seperempat siklus lebih dulu daripada sisi kiri.","docs.modules.width.title":"Lebar","docs.modules.width.p1":"Mempersempit atau memperlebar citra stereo, dari mono pada 0 % hingga 200 %, tanpa mengubah jumlah mono, dengan tunda Haas hingga 30 ms di sisi kanan untuk melebarkan vokal mono.","docs.modules.autopan.title":"Pan otomatis","docs.modules.autopan.p1":"Menggerakkan vokal dari sisi ke sisi dengan gelombang sinus atau segitiga, dengan rate dan depth: sebuah balance, jadi setiap sisi mempertahankan suaranya sendiri, dan di tengah keduanya lewat seperti saat masuk; ke arah satu sisi, sisi lain memudar, tidak pernah lebih keras daripada saat masuk.","docs.modules.shifter.title":"Penggeser Nada","docs.modules.shifter.p1":"Menggeser suara naik atau turun hingga dua oktaf, formannya digeser tersendiri hingga satu oktaf, dengan kontrol Mix: ad-lib satu oktaf lebih rendah. Seperti Penyetel Nada, ia menunggu 21 milidetik, atau 4 saat Tracking.","docs.project.p1":"Proyek Anda menyimpan chain, setiap modul dan kenop, tampilan, empat kenop Sederhana, kedua sisi perbandingan, dan apa yang didengarkan Penyetel Nada. Jika pengaturan sebuah proyek tidak dapat dibaca, proyek dibuka dengan chain bawaan dan memberitahukannya sekali, di atas area kerja, sampai Anda menutupnya.","docs.agreement.p1":"Saat pertama kali dibuka, Takelight menampilkan perjanjian lisensi dan penafiannya. Sampai Anda setuju, ia tidak melakukan apa pun selain meneruskan audio Anda tanpa perubahan, jadi menolak tidak pernah membuat sebuah trek senyap.","docs.agreement.p2":"Jawaban Anda disimpan di komputer Anda dan dipakai bersama oleh setiap salinan Takelight yang terbuka, di setiap DAW dan di aplikasi mandiri. Anda dapat membaca ulang perjanjian dan menerimanya kapan saja.","docs.settings.p1":"Di pengaturan Anda memilih terang atau gelap, bahasa, dan lainnya. Pilihan Anda milik komputer, bukan proyek: berlaku untuk setiap salinan Takelight di komputer itu.","docs.language.p1":"Takelight dan situs ini berbicara delapan belas bahasa, dengan bahasa Arab dari kanan ke kiri. Nama artis tidak pernah diterjemahkan.","docs.disclaimer.p1":"Nama artis menunjukkan sebuah gaya, tidak lebih. Freally Takelight tidak berafiliasi dengan, didukung, disponsori, atau disetujui oleh artis, produser, engineer, label, publikasi, atau pembuat plugin mana pun. Semua nama dan merek dagang milik pemiliknya, dan rupa, logo, tanda tangan, atau karya seni artis mana pun tidak digunakan di mana pun.","docs.disclaimer.p2":"Sebuah chain menerapkan pemrosesan; ia tidak mengubah siapa yang bernyanyi, dan tidak ada chain yang menjanjikan suara tertentu. Modul Takelight adalah rancangannya sendiri dan tidak mengaku sebagai produk lain.","docs.disclaimer.p3":"Ini adalah ringkasan. Takelight menampilkan penafian lengkap bersama perjanjian lisensinya.","docs.privacy.p1":"Plugin dan aplikasi mandiri tidak pernah online: tanpa akun, tanpa telemetri, dan tanpa kode jaringan, yang ditolak oleh gerbang build. Vokal Anda tidak pernah meninggalkan komputer, dan file referensi yang Anda muat untuk A/B hanya disimpan di memori.","docs.privacy.p2":"Mulai versi 1.0, sebuah pembantu terpisah memeriksa pembaruan dan mengaktifkan lisensi Anda — hanya saat Anda memintanya. Ia tidak pernah mengunduh atau memasang apa pun.","docs.report.p1":"Tulis ke freallyproducts@gmail.com. Saat Takelight sendiri gagal, pesan yang ditampilkannya menawarkan Laporkan: ia membuka halaman di peramban Anda sendiri yang menunjukkan semua yang akan dikirim, dan tidak ada yang meninggalkan komputer sampai Anda menekan Kirim. Setelah crash, peluncuran berikutnya menawarkan hal yang sama.","roster.lede":"Setiap artis dan genre yang punya chain vokal di plugin, era demi era.","roster.numbers.chains":"chain vokal","roster.numbers.artists":"artis","roster.numbers.genres":"genre","roster.title":"Daftar gaya","roster.placeholder":"Nama, genre, atau era","roster.search":"Cari","roster.col.type":"Jenis","roster.all":"Semua","roster.artists":"Artis","roster.genres":"Genre","roster.col.name":"Gaya","roster.col.era":"Era","roster.col.roles":"Chain vokal","roster.col.genre":"Genre","roster.loading":"Memuat daftar gaya…","roster.type.artist":"Artis","roster.type.genre":"Genre","roster.role.lead":"Lead","roster.role.adlib":"Ad-lib","roster.role.double":"Double","roster.role.harmony":"Harmoni","roster.role.fx":"FX","roster.era.decade":"Era {year}-an","roster.era.modern":"Era modern","roster.era.classic":"Era klasik","roster.era.record":"Era {record}","roster.shown":"{shown} dari {total} cocok","roster.none":"Tidak ada yang cocok.","roster.failed":"Daftar gaya tidak dapat dimuat. Coba muat ulang halaman.","roster.file":"Halaman ini dibuka sebagai berkas lokal, dan peramban menolak memuat daftar gaya dari halaman file://. Buka melalui HTTP sebagai gantinya.","kit.skip":"Lompat ke konten","kit.nav.site":"Situs","kit.nav.home":"Beranda","kit.nav.features":"Fitur","kit.nav.documentation":"Dokumentasi","kit.nav.roster":"Daftar","kit.nav.changelog":"Log perubahan","kit.nav.language":"Bahasa","kit.nav.allApps":"Semua aplikasi Freally","kit.badge.progress":"v0.6.1 selesai · berikutnya v0.7.0","kit.cta.features":"Lihat semua fitur","kit.cta.docs":"Baca dokumentasi","kit.noDownloads":"Belum ada unduhan, dan kode sumbernya bersifat pribadi.","kit.label.overview":"Ikhtisar","kit.label.inside":"Di dalamnya","kit.label.roadmap":"Peta jalan","kit.ladder.done":"Selesai","kit.ladder.planned":"Direncanakan","kit.ladder.goal":"Tujuannya","kit.ladder.later":"Nanti","kit.label.honesty":"Kejujuran","kit.family.label":"Keluarga Freally","kit.family.title":"<span class=\"hl-muted\">Satu keluarga.</span> <span class=\"hl-bright\">Sepuluh aplikasi.</span>","kit.cta.label":"Apa yang berubah","kit.cta.title":"<span class=\"hl-muted\">Setiap versi,</span> <span class=\"hl-bright\">tercatat.</span>","kit.cta.lede":"Log perubahan mencatat semua yang berubah di Freally Takelight, versi demi versi, dalam kedelapan belas bahasa.","kit.cta.changelog":"Baca log perubahan","kit.footer.thisApp":"Aplikasi ini","kit.footer.family":"Keluarga Freally","kit.status.devVersion":"Dalam pengembangan · v0.6.1","kit.head.features":"<span class=\"hl-muted\">Semua yang dilakukannya,</span> <span class=\"hl-bright\">berdampingan.</span>","kit.label.numbers":"Dalam angka","kit.numbers.lead":"Setiap angka dihitung dari aplikasinya sendiri. Tidak ada yang diperkirakan, dan tidak ada yang dibulatkan ke atas.","kit.label.free":"Gratis hari ini","kit.label.compare":"Perbandingan","kit.label.principles":"Prinsip","kit.label.limits":"Batasan","kit.states.title":"Arti setiap status","kit.states.done":"sudah dibangun dan diberi tag, tetapi bukan unduhan di situs ini","kit.states.planned":"masih akan dibangun","kit.states.goal":"versi yang menjadi tujuan jalan ini","kit.states.later":"setelah itu, dan belum dijadwalkan","kit.states.ladder":"Lihat setiap anak tangga di jalan ini","kit.head.documentation":"<span class=\"hl-muted\">Cara kerjanya,</span> <span class=\"hl-bright\">langkah demi langkah.</span>","kit.search.placeholder":"Cari dalam dokumentasi","kit.docs.contents":"Daftar isi","kit.head.roster":"<span class=\"hl-muted\">Setiap gaya,</span> <span class=\"hl-bright\">dalam satu daftar.</span>","kit.label.styles":"Gaya","kit.head.changelog":"<span class=\"hl-muted\">Setiap perubahan,</span> <span class=\"hl-bright\">versi demi versi.</span>","kit.changelog.lede":"Terbaru lebih dulu: semua yang berubah di Freally Takelight, dalam setiap bahasa situs ini.","kit.changelog.versions":"Versi","kit.search.none":"Tidak ada yang cocok di situs ini.","kit.zoom.close":"Tutup","changelog.f95683ba9422":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.1</span><time class=\"release__date\" datetime=\"2026-10-28\">2026-10-28</time></span><span class=\"release__title\">Gelombang pertama lengkap</span>","changelog.c4df85f5a8f5":"Sisa gelombang pertama: empat modul baru dan dua mode baru, tujuh chain lagi yang membutuhkannya, dan dua belas artis lagi.","changelog.6b02e0d363a4":"Ditambahkan","changelog.40209e252617":"<strong>Penekan Resonansi</strong> — menemukan bagian tempat suara Anda berdengung di atas frekuensi di sekitarnya dan hanya menurunkan bagian itu, hanya selama berdengung, di rentang yang Anda tentukan. Ia tidak pernah melihat ke depan, jadi tidak menambah latensi dan bekerja saat Anda merekam.","changelog.b43956f634d4":"<strong>Pembentuk Transien</strong> — mengangkat atau melunakkan awal setiap suara dengan Attack, dan dengungnya dengan Tahan, apa pun levelnya; nada yang ditahan lewat tanpa diubah. Kartunya menggambar satu pukulan sebelum dan sesudah.","changelog.7b02441ac0e0":"<strong>Ducker Spektral</strong> — di kanal return, delay atau reverb menyingkir dari jalan vokal Anda hanya di frekuensi yang diisi vokal Anda, lalu kembali di antara frasa.","changelog.da714ee8ef00":"<strong>Pompa</strong> — menurunkan vokal Anda di setiap ketukan, atau setiap bar, setengah, seperdelapan, atau seperenam belas not, lalu mengembalikannya mengikuti kurva, selaras dengan proyek Anda. Kartunya menggambar penurunannya sepanjang satu bar.","changelog.ae63cc9c793a":"<strong>Kilau</strong> — karakter keenam reverb: ekor gaung aula berputar sekali lagi satu oktaf lebih tinggi, sebanyak yang diizinkan kenop Kilau.","changelog.27fe8f8a733d":"<strong>Kompresi ke atas di Kompresor multiband</strong> — setiap band mengangkat apa yang jatuh di bawah ambang naiknya, hingga batas yang Anda tentukan; pada 1:1 tidak ada yang diangkat, jadi chain sebelumnya terdengar seperti dulu.","changelog.90f9e62dcb2d":"<strong>Tujuh chain lagi</strong> — Olivia Rodrigo, Taylor Swift, Dua Lipa, Young Thug, BTS, Bebe Rexha, dan Panic! at the Disco, masing-masing di era sebuah album.","changelog.394f8ff372ad":"<strong>Dua belas artis lagi</strong> — Lady Gaga dalam dua era, Lewis Capaldi, Sara Bareilles, The 1975, NF, Mike Posner, Lil Nas X, Robin Thicke, Olivia Dean, Muse, Tinchy Stryder, dan Tones And I.","changelog.2281e704f26e":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-28\">2026-10-28</time></span><span class=\"release__title\">Gelombang artis pertama</span>","changelog.68aa0830d2bd":"Empat puluh artis lagi, chain lead dan chain ad-lib untuk setiap genre di daftar, dan lima modul yang dibutuhkan chain baru, masing-masing dengan kartu yang menggambarkan apa yang dilakukannya. Situs dokumentasi memuat setiap chain di halaman Daftar gaya.","changelog.9c62a6f2c632":"<strong>Empat puluh artis lagi</strong> — masing-masing di era sebuah rekaman atau sebuah dekade, dari Adele hingga Twice, dan Cardi B serta DaBaby juga dengan chain ad-lib. Cari sebuah nama, seperti sebelumnya.","changelog.b471eaf5aa38":"<strong>Satu chain untuk setiap genre</strong> — setiap dari 73 genre di daftar, dari afrobeats dan amapiano hingga UK garage dan West Coast club, punya chain lead dan chain ad-lib sendiri; trap punya keduanya untuk 2000-an dan 2010-an. Artis di daftar yang belum punya chain sendiri ditawari chain genrenya.","changelog.285827d2c500":"<strong>EQ Dinamis</strong> — dua band, masing-masing bell atau shelf, yang memotong atau menaikkan hanya saat vokal Anda melewati ambangnya, sejauh rentangnya mengizinkan. Kartunya menggambarkan seluruh rentang dan posisi setiap band saat ini.","changelog.05e32f63742f":"<strong>Kompresor multiband</strong> — kompresor dalam tiga band, rendah, tengah, dan tinggi, dipisah di titik yang Anda tentukan, setiap band dengan ambang, rasio, dan gain-nya sendiri. Saat tidak ada yang dikurangi, ketiganya kembali menjumlah menjadi vokal Anda seperti semula.","changelog.5ed52e2ef910":"<strong>Flanger dan phaser</strong> — flanger menyapukan delay pendek terhadap vokal Anda, dan phaser menyapukan 4, 8, atau 12 tahap di sekitar frekuensi yang Anda tentukan; masing-masing punya laju, kedalaman, umpan balik, dan mix.","changelog.0ad4c2ec445b":"<strong>Pan otomatis</strong> — memindahkan vokal Anda di antara kiri dan kanan, sebagai sinus atau segitiga, dengan laju dan kedalaman yang Anda tentukan; sisi yang ditinggalkannya memudar, dan tidak ada sisi yang pernah dinaikkan.","changelog.370c2eaa669e":"<strong>Klip</strong> — karakter kelima untuk Saturasi: meratakan puncak dengan keras, dengan sudut yang cukup lembut agar tetap bersih.","changelog.d784579bd786":"<strong>Halaman Daftar gaya</strong> — situs dokumentasi memuat setiap artis dan genre yang punya chain, era demi era, dengan chain yang dimiliki masing-masing: lead, ad-lib, FX.","changelog.2a6141e43be0":"Diubah","changelog.af0704823374":"<strong>Empat delay jatuh di not seperdelapan</strong> — delay ad-lib era modern Drake, R&amp;B klasik, dan trap 2010-an, serta delay chain lead R&amp;B klasik, kini berulang di not seperdelapan sebagaimana mestinya, bukan di seperdelapan bertitik.","changelog.1231a0c0224a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.6</span><time class=\"release__date\" datetime=\"2026-10-27\">2026-10-27</time></span><span class=\"release__title\">Kartu visual</span>","changelog.ca7f81d415d0":"Kartu setiap modul kini menunjukkan apa yang dilakukannya, bukan hanya kenopnya: EQ menggambar kurvanya di atas vokal Anda saat diputar, kompresor menunjukkan di mana vokal Anda berada dan seberapa banyak yang diredamnya, dan sisanya menggambar pengulangan, peluruhan, citra stereo, dan kurvanya. Setiap gambar dihitung dari matematika yang sama yang menghasilkan suaranya.","changelog.c885adad0ca5":"<strong>Kartu EQ</strong> — EQ Parametrik, EQ Konsol, dan EQ Program menggambar kurvanya di atas spektrum langsung vokal Anda, sebelum EQ (redup) dan sesudahnya (terang), dengan puncak-puncaknya ditahan sejenak. Setiap band memiliki titik di kurva: seret untuk menggeser frekuensi dan gain-nya sekaligus, putar roda mouse di atasnya untuk mengatur lebarnya, klik ganda untuk mengembalikannya, atau gunakan tombol panah. Titik-titik EQ Program berpindah di antara frekuensinya, seperti kenopnya, dan titik-titik Kelas A pada EQ Konsol berada di langkah-langkah yang diambilnya. De-esser menggambar band yang didengarkannya dan potongan yang dibuatnya, dan Trim menggambar high-pass-nya.","changelog.e4155cb8a38e":"<strong>Kartu kompresor</strong> — Kompresor Optik, FET, VCA, vari-mu, dan Punch, Leveler Vokal, Penyetara level otomatis, dan Limiter menggambar kurvanya, level input terhadap level output, dengan titik di tempat vokal Anda berada pada kurva saat ini dan, di bawahnya, reduksi gain empat detik terakhir. Seret ambang batas di sepanjang kurva, atau gunakan tombol panah; itu memutar kenop yang mengaturnya.","changelog.ec53ddb6a430":"<strong>Kartu Gate</strong> — kurvanya, dan di bawahnya level yang didengarnya terhadap ambang batasnya selama empat detik terakhir, diarsir di bagian saat ia tertutup.","changelog.7c482c32b414":"<strong>Kartu modul ruang</strong> — pengulangan Penunda pada garis waktu terhadap ketukan dan birama proyek Anda, masing-masing sekeras yang disisakan oleh umpan balik dan filter (pada Ping-pong, yang kiri di atas garis, yang kanan di bawahnya); peluruhan Gaung — pra-tunda, pantulan awal, dan ekornya; kresendo Gate terbalik; dan citra stereo Pengganda, Efek chorus, dan Lebar, dilihat dari atas.","changelog.580a2bd46885":"<strong>Kartu modul warna</strong> — Saturasi, Eksiter, dan Efek lo-fi menggambar kurvanya dan, di sampingnya, harmonik yang ditambahkan kurva itu pada vokal Anda saat ini.","changelog.4aa1a07ba478":"<strong>Seretan atas dua kenop adalah satu langkah urungkan</strong> — menggeser titik band EQ mengubah frekuensi dan gain-nya sekaligus, dan satu kali Urungkan membatalkan seluruh seretan, berapa pun lamanya Anda menahannya diam.","changelog.c64f3e0add84":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.5</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">Input Check, ad-lib &amp; preset</span>","changelog.f6741058398a":"Atur level Anda sebelum merekam, simpan versi Anda sendiri dari chain mana pun, dan urungkan perubahan apa pun dengan satu tombol. Auto Key pada Penyetel Nada kini bisa menemukan tangga nada dari beat.","changelog.145f9c7721e2":"<strong>Input Check</strong> — tekan Input Check di rack lalu nyanyikan atau mainkan take Anda selama sepuluh detik; lampu rekam menyala amber selama ia mendengarkan. Lalu ia menunjukkan yang terdengar (puncak, level, kenyaringan, derau dasar, gemuruh, sibilansi, dan plosif) dan yang disarankan: Kenop Input, serta gate, filter high-pass, dan de-esser yang sudah ada di chain. Tidak ada yang berubah sampai Anda menekan Terapkan, dan modul yang tidak ada di chain memberitahukannya — tidak ada yang ditambahkan untuk Anda. Jika take mengalami clipping, ia meminta Anda menurunkan gain interface Anda.","changelog.807271b61fd0":"<strong>Preset Anda</strong> — Simpan preset… menyimpan chain seperti yang telah Anda bentuk, dengan nama pilihan Anda, sebagai file di Dokumen › Freally Takelight › Presets. Preset saya… memuat, mengganti nama, mengekspor, dan menghapusnya, serta mengimpor preset yang dikirim seseorang kepada Anda (file yang bukan preset ditolak, beserta alasannya). Preset Anda juga muncul di pencarian, di bawah Preset saya, dengan chain asal masing-masing. Saat chain itu diperbarui, preset Anda mengikutinya dan mempertahankan suntingan Anda.","changelog.2110305b2ce9":"<strong>Urungkan dan ulangi</strong> — setiap perubahan pada suara, hingga 100 langkah: sebuah kenop (satu langkah per seretan), modul yang ditambahkan atau dikeluarkan, karakternya, Bypass dan Solo, kirim dan fader, empat kenop besar, Kenop Input, chain atau preset yang dimuat, dan Terapkan dari Input Check. Panah di bilah atas, atau Ctrl+Z dan Ctrl+Shift+Z (juga Ctrl+Y; ⌘Z dan ⌘⇧Z di Mac) selama jendela sedang fokus. Tampilan, tema, bahasa, dan referensi A/B tidak pernah diurungkan, begitu pula otomatisasi DAW Anda; beralih antara A dan B memulai riwayat sisi itu dari awal.","changelog.065bc3159eeb":"<strong>Kenop Input</strong> — di samping meter Input, level yang masuk, dari −24 hingga +24 dB. Input Check mengaturnya, dan DAW Anda dapat mengotomatiskannya.","changelog.0c42df2ca995":"<strong>Auto Key dari beat</strong> — Penyetel Nada bisa mendengarkan input sidechain: kirim beat Anda ke sidechain Freally Takelight dan pilih <em>Mendengarkan: Sidechain</em> di kartu Penyetel Nada, dan Auto Key mengikuti akor beat, bukan suara Anda. Setiap proyek mengingat pilihannya; Pengaturan menetapkannya untuk proyek baru. Saat tidak ada yang diputar di sidechain, Penyetel Nada mendengarkan vokal Anda dan memberitahukannya.","changelog.057d5c78c13a":"<strong>Dialog Buka dan Simpan menjadi bagian dari jendela</strong> — dialog itu terbuka di depan Freally Takelight dan menahannya di belakang sampai Anda selesai memilih.","changelog.adf9645e2b40":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">Cahaya pertama — Drake &amp; penjelajah chain</span>","changelog.9befafdec87e":"Versi lengkap pertama: cari artis, pilih era, tekan putar, dan seluruh chain vokal dimuat dengan satu klik. Era-era Drake dan delapan belas chain genre hadir, dengan empat kenop besar untuk membentuknya, referensi sebagai pembanding, dan versi kedua chain Anda untuk dibandingkan.","changelog.abd39e3e1804":"<strong>Penjelajah chain</strong> — ketik artis atau genre di pencarian (Ctrl+K, atau Cmd+K di Mac), dan chain tersusun menurut era dan peran saat Anda mengetik, termasuk nama julukan. Saat kolomnya kosong, ia menawarkan chain yang terakhir Anda muat; untuk artis yang belum ada di pustaka, ia menyarankan chain genre. Setiap langkah bisa dilakukan dari papan ketik.","changelog.6372ffc30569":"<strong>Drake</strong> — tiga era: Era So Far Gone (2009), Era Take Care (2011), dan Era modern (2016–2026), satu lead untuk masing-masing dan satu ad-lib untuk era modern, serta chain FX dari era Take Care yang hanya hidup di kanal return.","changelog.8def9e786270":"<strong>Delapan belas chain genre</strong> — lead dan ad-lib untuk trap (2000-an dan 2010-an), Chicago drill, emo rap, R&amp;B klasik, pop modern, rock, country pop, dan reggaeton.","changelog.3370f1b4141c":"<strong>Mode Sederhana</strong> — lampu rekam, nama chain, empat kenop besar, dan meter Input/Output; Lanjutan menampilkan seluruh rack. Setiap proyek mengingat mode terakhirnya, dan di Pengaturan Anda memilih mode untuk instans baru.","changelog.b4ff7f2e9dce":"<strong>Empat kenop</strong> — Penyetel Nada (seberapa cepat dan seberapa alami vokal disetel), Warna Suara (lebih gelap atau lebih terang, dengan de-esser mengikuti), Ruang (semua level kirim efek bersama-sama), dan Takaran (seluruh chain terhadap vokal kering Anda). Dengan Penyetel Nada, Warna Suara, dan Ruang di tengah serta Takaran penuh, chain berbunyi seperti saat dibuat, dan setiap chain dimuat dengan cara itu. DAW Anda dapat mengotomatisasi keempatnya.","changelog.8988c7fcad46":"<strong>Referensi A/B</strong> — buka lagu atau vokal yang sudah jadi (WAV, AIFF, FLAC, atau MP3, hingga 20 menit), atau letakkan di jendela, dan B memutarnya dari posisi DAW Anda (dari awal di aplikasi mandiri), dengan crossfade 20 ms dan kenyaringan yang disamakan dengan vokal Anda, jadi Anda menilai warna suaranya, bukan levelnya. Referensi hanya disimpan di memori: tidak pernah disimpan bersama proyek, preset, atau di tempat lain mana pun, dan file di drive jaringan ditolak.","changelog.41af758b9239":"<strong>Perbandingan chain</strong> — dua versi chain Anda, A dan B: B dimulai sebagai salinan A, masing-masing menyimpan suntingannya sendiri, dan satu klik beralih di antara keduanya.","changelog.595ee8591a1b":"<strong>Proyek mengingat</strong> — chain, tampilan, kenop Sederhana, dan kedua sisi perbandingan disimpan bersama proyek Anda. Proyek yang tidak dapat dibaca dibuka dengan chain bawaan dan memberitahukannya sekali.","changelog.4794b815283f":"<strong>Kursor Freally</strong> — sebuah cincin dengan titik di tengahnya, yang membesar di atas apa pun yang bisa Anda tekan.","changelog.3ad2505d4a1e":"<strong>Sakelar</strong> — setiap sakelar berwarna abu-abu saat mati, putih di bawah penunjuk, dan hijau Freally saat menyala, baik di bawah penunjuk maupun tidak.","changelog.d526eacf003a":"<strong>Rack penuh memberi tahu</strong> — sebuah rack memuat kenop sebanyak yang dapat digerakkan Freally Takelight sekaligus; modul yang melewati batas itu ditolak dengan pesan bahwa rack sudah penuh.","changelog.81c6aadde005":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">Penyetel Nada</span>","changelog.ee8aa777588f":"Koreksi nada hadir: Penyetel Nada menarik vokal Anda ke nada-nada dalam tangga nadanya dengan forman tetap terjaga, menemukan tangga nada sendiri, dan turun ke beberapa milidetik latensi saat Anda merekam; dan Penggeser Nada menggeser suara naik atau turun hingga dua oktaf.","changelog.e84a04d8e61c":"<strong>Penyetel Nada</strong> — koreksi nada dengan pemrosesan sinyal klasik: kecepatan koreksi dari 0 ms (suara keras yang berundak) hingga 400 ms, Humanisasi agar nada panjang bisa bernapas, dan Kelenturan untuk menjaga luncuran dan vibrato. Suara Anda tetap berkarakter, karena formannya tetap di tempatnya.","changelog.1b908b3463cd":"<strong>Auto Key</strong> — Penyetel Nada mendengarkan vokal Anda dan menetapkan tangga nadanya dalam sekitar empat detik nyanyian, tetap kromatik sampai saat itu. Kunci tangga nada yang didengarnya dengan satu klik, atau pilih salah satu dari 24 tangga nada, atau Kromatik.","changelog.539fbc62230d":"<strong>Grafik nada</strong> — empat detik terakhir suara Anda, nada yang dinyanyikan dan nada yang disetel, di bawah nada yang ditujunya.","changelog.0f378cb53cb4":"<strong>Tracking</strong> — saat DAW Anda merekam (atau saat Anda menyalakannya), Penyetel Nada bekerja dengan latensi beberapa milidetik sehingga Anda bisa bernyanyi melalui chain; saat mixing, ia melaporkan latensi penuhnya agar DAW Anda menjaga vokal tetap seirama dengan beat.","changelog.2e82019ea87e":"<strong>Penggeser Nada</strong> — menggeser suara naik atau turun hingga dua oktaf, formannya digeser tersendiri hingga satu oktaf, dicampur dengan suara aslinya: ad-lib satu oktaf lebih rendah.","changelog.ba9e41780afd":"<strong>Lampu rekam mendengarkan</strong> — menyala amber selama Auto Key masih mendengarkan untuk mencari tangga nada.","changelog.e86e8d397ace":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">Ruang</span>","changelog.c223312c046d":"Empat kanal return efek hadir, dengan penunda, gaung, penggandaan, dan lebar yang seirama dengan proyek Anda, tombol Lempar di setiap kanal return, dan empat modul tambahan untuk insert.","changelog.eaa251798d7e":"<strong>Empat kanal return efek</strong> — A hingga D, masing-masing diumpankan dari ujung insert lewat kenop Kirim-nya, dengan tiga slot dan fader sendiri, bergabung dengan vokal kering dalam perjalanannya ke bus vokal.","changelog.ebb30e23847f":"<strong>Lemparan</strong> — tahan tombol Lempar sebuah kanal return dan vokal dilempar ke dalamnya, dengan level kirimnya di 0 dB sampai Anda melepasnya. Lempar A hingga D juga merupakan parameter host, jadi DAW Anda bisa merekam lemparan dan memutarnya kembali.","changelog.39cab35a5560":"<strong>Penunda</strong> — Digital, Pita magnetik, Analog, Ping-pong, dan Gema pendek, diatur dalam milidetik atau sebagai nilai not yang seirama dengan proyek Anda, dengan filter di umpan balik, peredaman di bawah vokal, dan lebar.","changelog.d45fe717d01c":"<strong>Gaung</strong> — Pelat, Ruangan, Aula, Ruang gema, dan Suasana, dengan peluruhan dari 0.1 hingga 20 detik; dan <strong>Gate terbalik</strong>, gaung terbalik yang membesar tanpa menambah latensi.","changelog.4db2c68f321a":"<strong>Pengganda, Efek chorus, dan Lebar</strong> — dua hingga empat suara dari satu rekaman, chorus dua suara, dan lebar stereo dari mono hingga 200 % dengan tunda Haas.","changelog.8be315d62f9e":"<strong>Empat modul tambahan untuk insert</strong> — Kompresor vari-mu dengan enam konstanta waktu, Penyetara level otomatis, Eksiter, dan Efek lo-fi.","changelog.2d718978085b":"<strong>Seirama dengan proyek Anda</strong> — penunda yang diatur ke nilai not mengikuti tempo DAW Anda, bahkan saat tempo berubah di tengah lagu.","changelog.e3c80cfe9d31":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span><span class=\"release__title\">Joint, modul pertama &amp; situs dokumentasi</span>","changelog.521a85ebded1":"Rack hadir: satu Joint untuk seluruh chain vokal, tiga belas modul rancangan Takelight sendiri di perangkat keras yang dirender, dan lampu rekam.","changelog.657c896de46f":"<strong>Joint</strong> — satu rack sesuai urutan sinyal: tahap awal dua slot, dua belas insert, dan bus vokal empat slot, DAW Anda diberi tahu latensinya, dengan Takaran memadukan seluruh chain dengan vokal kering.","changelog.44955680f91b":"<strong>Perubahan bebas klik</strong> — tambah, hapus, dan tukar modul sambil trek diputar: rack baru disiapkan terpisah dari audio dan masuk dengan crossfade 30 milidetik, karakter baru masuk dengan crossfade, dan setiap kenop bergerak halus.","changelog.5883cafdd389":"<strong>Tiga belas modul</strong> — Trim; EQ Parametrik, Konsol, dan Program; kompresor Optik, FET, VCA, dan Punch; Leveler Vokal; De-esser; Gate; Saturasi; dan Limiter true-peak.","changelog.da4d68a37948":"<strong>Layar rack</strong> — setiap modul berupa kartu perangkat keras yang dirender, dengan karakter, Bypass, Solo, dan reduksi gain, setiap kontrol bisa dijangkau dari papan ketik, dalam 18 bahasa.","changelog.19b404056636":"<strong>Otomatisasi</strong> — 24 parameter host setiap slot menggerakkan kontrol modulnya secara berurutan, sehingga daftar parameter tidak pernah berubah.","changelog.93ce19272231":"<strong>Lampu rekam dan meter</strong> — lampu bilik rekaman, dirender di Blender dalam versi gelap dan terang, menyala hijau saat ada modul di rack dan suara Anda masuk, dan berkedip merah saat clipping; meter Input dan Output dengan lampu clip.","changelog.54bf2d68a5db":"<strong>Laporkan ini</strong> — saat Takelight sendiri gagal, atau setelah crash, sebuah halaman di peramban Anda sendiri menunjukkan semua yang akan dikirim sebuah laporan, dan tidak ada yang dikirim sampai Anda menekan Kirim.","changelog.42b61e5ef13f":"<strong>Situs dokumentasi, lengkap</strong> — beranda, fitur, manual, catatan perubahan, dan tangga versi, dalam 18 bahasa.","changelog.2178abb38e7d":"<strong>Perjanjian lisensi kini versi 2</strong>, jadi Takelight meminta Anda menerimanya sekali lagi. Perjanjian dan penafian kini lebih pendek dan lebih lugas.","changelog.e6a2eb660b78":"<strong>Satu pengaturan berkurang</strong> — titik berwarna di samping nilai sudah hilang, begitu pula pengaturannya. Kredit hanya mencantumkan pemberitahuan lisensi.","changelog.5758b5c96327":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.1</span><time class=\"release__date\" datetime=\"2026-10-13\">2026-10-13</time></span><span class=\"release__title\">Pengaturan, digambar ulang</span>","changelog.898338328178":"<strong>Pengaturan, digambar ulang</strong> — dibuka dari roda gigi di bilah atas dan ditutup dengan ×; tema berupa sakelar gelap/terang dengan bulan dan matahari, setiap pilihan singkat berupa kontrol bersegmen dengan penggeser, dan teks panjang di Tentang berupa daftar baris.","changelog.5c7b3a54f6e0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span><span class=\"release__title\">Fondasi, tulang punggung CI, dan jalur rilis</span>","changelog.e7f1a5798692":"Freally Takelight kosong yang termuat di host, meneruskan audio, dan sudah punya setiap gerbang, kedua jalur CI, serta jalur rilis sebelum satu fitur pun ada.","changelog.82a7fc560af2":"<strong>Plugin, kosong, dalam setiap format</strong> — CLAP dari nih-plug, VST3 dan AU yang diproyeksikan clap-wrapper dari biner yang sama, serta aplikasi mandiri. Input mono dan stereo, output stereo; audio lewat tanpa perubahan.","changelog.9dc28fd94514":"<strong>Kumpulan parameter</strong> — input, output, takaran, bypass, tracking, tiga makro, empat throw, dan 30 slot berisi 24 parameter generik, sehingga memuat chain tidak pernah mengubah daftar parameter host.","changelog.7a8b66c5fe5a":"<strong>Cangkang editor</strong> — kit UI Freally dalam gelap dan terang, EULA dan penafian saat pertama dijalankan, Pengaturan dan Tentang, 18 bahasa dengan tata letak kanan ke kiri.","changelog.ec039c3098d0":"<strong>Gerbang</strong> — tanpa AI, tanpa jaringan, tanpa kode pinjaman, nama produk dan kata terlarang, tanpa unduhan sebelum 1.0, tangga versi, lisensi, crate bersama, kit UI dan seni perangkat keras, bahasa dan CSS logis, pergeseran binding, dan tanpa alokasi di thread audio.","changelog.872b0df7744d":"<strong>CI yang di-host sendiri</strong> — <code>npm run ci:local</code> (Windows) dan <code>npm run ci:linux</code> (Docker Desktop), satu daftar gerbang; Playwright terhadap editor dan terhadap aplikasi mandiri sungguhan.","changelog.5cbd8ff53c0a":"<strong>Jalur rilis</strong> — <code>npm run release:local</code> membangun tepat tag tersebut, memvalidasi bundel, menulis folder rilis dengan checksum, memangkas <code>target/</code> hingga tinggal folder itu, dan memasang VST3 serta CLAP lewat satu prompt UAC.","changelog.4e9699d53d2d":"<strong>Kerangka situs dokumentasi</strong> dan kerangka data chain (<code>tlc validate</code>, <code>tlc import-roster</code>)."};
